/* GeoMannequin — POSES DE GRUPO (duplas, trios, grupos de 4, 5, 6, 8 e 12): cada uma diz onde fica cada papel (x, z em metros,
   giro em graus: 0 = de frente para +z), a pose, para quem olha, os contatos (interações entre dois) e os objetos de apoio.
   Uso no texto (Name e barra do palco): grupo-pose ID [com Kai, Mira, …] [em (x,z)] [gira G] [espelhado] [nome Figurante]
   Quem faltar vira figurante (Figurante1, Figurante2…). MCP: grupo_pose. Catálogo: catalogo-poses.js. */
import { INTERACOES_NARRATIVAS } from "./interacoes-narrativas.js";
import { POSES_CORPO, POSE0 } from "./poses.js";
const GRUPOS_POSES = {};
const GP_D = Math.PI / 180, gpF = v => (Math.round(v * 100) / 100).toString();
/* gp(id, "nome pt|apelido", "english", "Categoria/Sub", papeis, extra)  papeis: [[pose, x, z, giro, olha?], …] (olha: índice do outro papel) */
function gp(id, pt, en, tag, papeis, x = {}) { if (GRUPOS_POSES[id]) throw new Error("grupo-pose repetido: " + id); const ap = pt.split("|");
  GRUPOS_POSES[id] = Object.assign({ id, nome: ap[0], apelidos: ap, en, tag, n: papeis.length, papeis: papeis.map(p => ({ pose: p[0], x: p[1], z: p[2], g: p[3] || 0, olha: p[4] ?? null })) }, x); }
/* formações (devolvem [[x, z, giro], …]) */
const gpGiroPara = (p, a) => Math.round(Math.atan2(a[0] - p[0], a[1] - p[1]) / GP_D);
const gpLinha = (n, e = 0.9, g = 0) => Array.from({ length: n }, (_, i) => [(i - (n - 1) / 2) * e, 0, g]);
const gpFila = (n, e = 0.9, g = 0) => Array.from({ length: n }, (_, i) => [0, -i * e, g]);
const gpRoda = (n, r = 1.2) => Array.from({ length: n }, (_, i) => { const a = i / n * Math.PI * 2, p = [Math.sin(a) * r, Math.cos(a) * r]; return [p[0], p[1], gpGiroPara(p, [0, 0])]; });
const gpArco = (n, r = 2, abre = 120, alvo = [0, 0]) => Array.from({ length: n }, (_, i) => { const a = (-abre / 2 + (n > 1 ? abre * i / (n - 1) : 0)) * GP_D, p = [alvo[0] + Math.sin(a) * r, alvo[1] + Math.cos(a) * r]; return [p[0], p[1], gpGiroPara(p, alvo)]; });
const gpGrade = (n, cols, ex = 0.9, ez = 0.9, g = 0) => Array.from({ length: n }, (_, i) => [((i % cols) - (Math.min(cols, n) - 1) / 2) * ex, -Math.floor(i / cols) * ez, g]);
const gpCunha = (n, e = 0.9, g = 0) => Array.from({ length: n }, (_, i) => { const k = Math.ceil(i / 2), s = i % 2 ? -1 : 1; return [i ? s * k * e * 0.8 : 0, -k * e, g]; });
const gpConfronto = (n, d = 3, e = 0.9) => { const a = Math.ceil(n / 2), b = n - a; return gpLinha(a, e).map(p => [p[0], -d / 2, 0]).concat(gpLinha(b, e).map(p => [p[0], d / 2, 180])); };
const gpDisperso = (n, raio = 2.5, semente = 3) => { let s = semente; const r = () => (s = (s * 9301 + 49297) % 233280) / 233280, P = []; for (let t = 0; P.length < n && t < 5000; t++) { const p = [(r() * 2 - 1) * raio, (r() * 2 - 1) * raio]; if (P.every(q => Math.hypot(q[0] - p[0], q[1] - p[1]) > 1.05)) P.push(p); } return P.map(p => [p[0], p[1], Math.round(r() * 360 - 180)]); };
/* gpT: um modelo para vários tamanhos — poses (lista que se repete), formação(n) */
function gpT(base, pt, en, tag, tamanhos, poses, forma, x = {}) { for (const n of tamanhos) { const F = forma(n); gp(base + n, pt.replace(/\{n\}/g, n), en.replace(/\{n\}/g, n), tag, F.map((p, i) => [typeof poses === "function" ? poses(i, n) : poses[i % poses.length], p[0], p[1], p[2], p[3]]), Object.assign({}, x, typeof x.objetos === "function" ? { objetos: x.objetos(n) } : {})); } }

/* ===================================================== DUPLAS COM CONTATO (as interações narrativas) ===================================================== */
