/* ===================================================== expandir (texto) ===================================================== */
const GP_SENT = new Map();
function gpSentado(pose) { if (GP_SENT.has(pose)) return GP_SENT.get(pose); let r = false; try { if (POSES_CORPO[pose]) { const v = Object.assign({}, POSE0); POSES_CORPO[pose](v, 1); r = ((v.hipFlexL || 0) + (v.hipFlexR || 0)) / 2 > 65 && ((v.kneeFlexL || 0) + (v.kneeFlexR || 0)) / 2 > 55 && ((v.kneeFlexL || 0) + (v.kneeFlexR || 0)) / 2 < 125 && Math.abs(v.bodyPitch || 0) < 40 && (v.bodyLift || 0) < 2; } } catch (e) { r = false; } GP_SENT.set(pose, r); return r; }
function gpAchar(id) { if (!id) return null; const s = String(id).replace(/"/g, "").replace(/^(grupo|inter|pose):(?=\w+\.)/i, ""); if (GRUPOS_POSES[s]) return GRUPOS_POSES[s]; const k = Object.keys(GRUPOS_POSES).find(x => x.toLowerCase() === s.toLowerCase() || x.toLowerCase().endsWith("." + s.toLowerCase())); return k ? GRUPOS_POSES[k] : null; }
function gpParecidos(id, n = 4) { const q = String(id).toLowerCase().replace(/[^a-z0-9]/g, ""); return Object.keys(GRUPOS_POSES).map(k => [k, k.toLowerCase().replace(/[^a-z0-9]/g, "")]).filter(([k, t]) => t.includes(q.slice(0, 6)) || q.includes(t.split(".").pop().slice(0, 6))).slice(0, n).map(x => x[0]); }
/* devolve { linhas, novos (nomes de figurantes para o elenco) } */
function gpLinhas(def, nomes, o = {}) { const x0 = o.x ?? 0, z0 = o.z ?? 0, g0 = (o.giro || 0) * GP_D, esp = o.espelhar ? -1 : 1, ns = nomes.slice(), novos = [], usados = new Set(o.usados || []);
  const q = n => /^[A-Za-zÀ-ÿ][\wÀ-ÿ]*$/.test(n) ? n : '"' + String(n).replace(/"/g, "") + '"';
  while (ns.length < def.n) { let k = 1, b = o.nome || "Figurante"; while (usados.has(b + k) || ns.includes(b + k)) k++; ns.push(b + k); novos.push(b + k); usados.add(b + k); }
  const objNomes = [], sentaEm = {}, mundo = (x, z) => { const lx = x * esp; return [x0 + lx * Math.cos(g0) + z * Math.sin(g0), z0 - lx * Math.sin(g0) + z * Math.cos(g0)]; }, giro = g => Math.round(((o.giro || 0) + g * esp + 540) % 360 - 180), L = [];
  for (const ob of def.objetos || []) { const [wx, wz] = mundo(ob[1], ob[2]), base = ob[0].replace(/([a-z])([A-Z])/g, "$1 $2").replace(/^./, c => c.toUpperCase()); let nm = base, k = 2; while (usados.has(nm)) nm = base + " " + k++; usados.add(nm); objNomes.push(nm); L.push("objeto " + ob[0] + ' "' + nm + '" em (' + gpF(wx) + "," + gpF(wz) + ") gira " + giro(ob[3] || 0)); }
  /* quem senta (quadril e joelho dobrados, de pé no chão) ganha uma cadeira atrás, virada para o mesmo lado (se o grupo não trouxer assentos) */
  if (def.sentados && def.cadeiras !== false && !(def.objetos || []).some(o => /cadeira|banco|sofa/.test(o[0]))) def.papeis.forEach((p, i) => { if (!gpSentado(p.pose)) return; const [wx, wz] = mundo(p.x, p.z); let nm = "Cadeira", k = 2; while (usados.has(nm)) nm = "Cadeira " + k++; usados.add(nm); objNomes.push(nm); sentaEm[i] = nm; L.push("objeto cadeira \"" + nm + "\" em (" + gpF(wx) + "," + gpF(wz) + ") gira " + giro(p.g || 0)); });
  def.papeis.forEach((p, i) => { const [wx, wz] = mundo(p.x, p.z); L.push(q(ns[i]) + " em (" + gpF(wx) + "," + gpF(wz) + ") gira " + giro(p.g) + (o.semPoses ? "" : " pose " + p.pose)); });
  def.papeis.forEach((p, i) => { if (sentaEm[i] && !o.semPoses) L.push(q(ns[i]) + ' senta-em "' + sentaEm[i] + '"'); });
  def.papeis.forEach((p, i) => { if (p.olha !== null && p.olha !== undefined && ns[p.olha] && p.olha !== i) L.push(q(ns[i]) + " olha " + q(ns[p.olha])); });
  for (const [a, b, t] of def.inter || []) L.push(q(ns[a]) + ", " + q(ns[b]) + " interacao " + t);
  return { linhas: L, novos, nomes: ns.slice(0, def.n), objetos: objNomes }; }
/* uma linha "grupo-pose ID [com A, B] [em (x,z)] [gira G] [espelhado] [sem-poses] [nome Base]" */
function gpLerLinha(txt) { const m = /^\s*grupo-pose\s+(\S+)\s*(.*)$/i.exec(String(txt)); if (!m) return null; const def = gpAchar(m[1]);
  if (!def) { const s = gpParecidos(m[1]); throw new Error("Pose de grupo “" + m[1] + "” não existe." + (s.length ? " Parecidas: " + s.join(", ") + "." : " Veja o Catálogo (tecla C) ou catalogo_poses no MCP.")); }
  let r = " " + m[2] + " "; const o = {};
  r = r.replace(/\s(?:em|no|na)\s*\(\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)\s*\)/i, (_, x, z) => { o.x = +x; o.z = +z; return " "; });
  r = r.replace(/\sgira\s+(-?[\d.]+)/i, (_, g) => { o.giro = +g; return " "; });
  r = r.replace(/\s(espelhad[oa]|invertid[oa])(?=\s)/i, () => { o.espelhar = true; return " "; });
  r = r.replace(/\ssem-poses?(?=\s)/i, () => { o.semPoses = true; return " "; });
  r = r.replace(/\snome\s+("[^"]+"|[\wÀ-ÿ]+)/i, (_, v) => { o.nome = v.replace(/"/g, ""); return " "; });
  let nomes = []; const mc = /\scom\s+(.+?)\s*$/i.exec(r); if (mc) { nomes = mc[1].split(/\s*,\s*|\s+e\s+/).map(s => s.trim().replace(/^"|"$/g, "")).filter(Boolean); r = r.slice(0, mc.index) + " "; }
  if (r.trim()) throw new Error("grupo-pose " + def.id + ": não entendi “" + r.trim() + "” (use: com Kai, Mira · em (x,z) · gira 90 · espelhado · sem-poses · nome Guarda).");
  if (nomes.length > def.n) throw new Error("grupo-pose " + def.id + " tem " + def.n + " papéis e você deu " + nomes.length + " nomes.");
  return { def, nomes, o }; }
function listaGruposPoses() { return Object.values(GRUPOS_POSES).map(d => ({ id: d.id, nome: d.nome, en: d.en, tag: d.tag, pessoas: d.n, contato: !!(d.inter && d.inter.length), objetos: (d.objetos || []).map(o => o[0]), poses: d.papeis.map(p => p.pose) })); }
export { GRUPOS_POSES, gp, gpT, gpAchar, gpLinhas, gpLerLinha, gpParecidos, gpRegistrarInteracoes, listaGruposPoses, GP_INTER };
